const LOGO = "data:image/png;base64,";
const IMG = Object.fromEntries(
  ["sable","belmore","peninsula","cabin","living","dliving","dsable","dpeninsula","amb-sable","amb-belmore","amb-peninsula","amb-cabin","amb-living","pb1-sable","pb2-sable","pb1-belmore","pb2-belmore","pb1-peninsula","pb2-peninsula","pb1-cabin","pb2-cabin","pb1-living","pb2-living","ryan","reille"]
    .map(k => [k, "assets/images/" + k + ".jpg"])
);
